"use strict";(globalThis.webpackChunkwebsite||=[]).push([[18673],{36327(r){r.exports=JSON.parse('{"tag":{"label":"\u6545\u4e8b\u521b\u4f5c","permalink":"/docs/tags/\u6545\u4e8b\u521b\u4f5c","allTagsPath":"/docs/tags","count":11,"items":[{"id":"lifeforfun/storycraft/archetypes","title":"\u539f\u578b\u4e0e\u6027\u683c\u7406\u8bba\u5730\u56fe","description":"\u628a\u8363\u683c\u539f\u578b\u3001\u574e\u8d1d\u5c14\u82f1\u96c4\u4e4b\u65c5\u3001\u6c83\u683c\u52d2\u7684\u89d2\u8272\u529f\u80fd\u3001\u5341\u4e8c\u539f\u578b\u3001\u5927\u4e94\u4eba\u683c\u3001\u4e5d\u578b\u4eba\u683c\u3001\u4f9d\u604b\u7c7b\u578b\u3001\u970d\u59ae\u7684\u4e09\u79cd\u4eba\u9645\u503e\u5411\u3001\u4f2f\u6069\u7684\u4ea4\u4e92\u5206\u6790\u4e0e\u6208\u592b\u66fc\u7684\u62df\u5267\u8bba\u644a\u5728\u4e00\u5f20\u684c\u4e0a\uff0c\u8bf4\u660e\u6bcf\u4e2a\u5de5\u5177\u89e3\u51b3\u54ea\u7c7b\u95ee\u9898\u3001\u4ee5\u53ca\u5b83\u4eec\u7684\u8fb9\u754c\u3002","permalink":"/docs/lifeforfun/storycraft/archetypes"},{"id":"lifeforfun/storycraft/methods","title":"\u5851\u9020\u65b9\u6cd5\uff1a\u4f5c\u8005\u7a76\u7adf\u505a\u4e86\u4ec0\u4e48","description":"\u628a\u4eba\u7269\u5851\u9020\u62c6\u6210\u53ef\u590d\u7528\u7684\u4e5d\u9053\u624b\u6cd5\uff1a\u6b32\u671b\u2014\u9700\u6c42\u2014\u8c0e\u8a00\u4e09\u89d2\u3001\u538b\u529b\u4e0b\u7684\u9009\u62e9\u3001\u884c\u4e3a\u5316\u7ec6\u8282\u3001\u5bf9\u767d\u4e0e\u6f5c\u53f0\u8bcd\u3001\u5173\u7cfb\u7f51\u5b9a\u4e49\u3001\u5f27\u7ebf\u8bbe\u8ba1\u3001\u53cd\u6d3e\u52a8\u673a\u5408\u7406\u5316\u3001\u4fa7\u9762\u7ec6\u8282\uff0c\u4ee5\u53ca\u65af\u5766\u5c3c\u5f0f\u573a\u666f\u63a8\u6f14\uff0c\u5e76\u7ed9\u51fa\u4e00\u5957\u4ece\u201c\u4e00\u53e5\u8bdd\u4eba\u8bbe\u201d\u5230\u201c\u80fd\u6f14\u7684\u4eba\u201d\u7684\u5de5\u4f5c\u6d41\u3002","permalink":"/docs/lifeforfun/storycraft/methods"},{"id":"lifeforfun/storycraft/index","title":"\u6545\u4e8b\u521b\u4f5c","description":"\u4ee5\u6545\u4e8b\u521b\u4f5c\u5207\u5165\u7684\u4eba\u7269\u5851\u9020\u77e5\u8bc6\u4f53\u7cfb\uff1a\u5148\u8bb2\u6e05\u4eba\u7269\u51ed\u4ec0\u4e48\u201c\u7acb\u201d\u8d77\u6765\uff0c\u518d\u7ed9\u539f\u578b\u7406\u8bba\u4e0e\u5851\u9020\u65b9\u6cd5\uff0c\u7136\u540e\u9010\u7c7b\u62c6\u89e3\u5c0f\u8bf4\u3001\u5f71\u89c6\u4e0e\u771f\u5b9e\u6848\u4f8b\uff0c\u6700\u540e\u843d\u5230\u8bc6\u4eba\u3001\u6c9f\u901a\u3001\u5171\u60c5\u3001\u8fb9\u754c\u3001\u51b2\u7a81\u4e0e\u81ea\u6211\u53d9\u4e8b\u3002","permalink":"/docs/lifeforfun/storycraft/"},{"id":"lifeforfun/storycraft/the-sage","title":"\u667a\u8005\u4e0e\u5bfc\u5e08\uff1a\u77e5\u8bc6\u3001\u6743\u5a01\u4e0e\u8fb9\u754c","description":"\u667a\u8005\u4e0d\u9760\u529b\u91cf\u4e0e\u9b45\u529b\uff0c\u9760\u77e5\u9053\uff1b\u4ed6\u7684\u529f\u80fd\u4e0d\u662f\u6253\u8d62\uff0c\u662f\u8ba9\u4eba\u770b\u89c1\u81ea\u5df1\u5df2\u7ecf\u77e5\u9053\u7684\u4e8b\u3002\u8fd9\u7bc7\u7528\u300a\u6740\u6b7b\u4e00\u53ea\u77e5\u66f4\u9e1f\u300b\u7684\u963f\u63d0\u514b\u65af\u3001\u300a\u6b7b\u4ea1\u8bd7\u793e\u300b\u7684\u57fa\u5ef7\u4e0e\u82cf\u683c\u62c9\u5e95\u505a\u6848\u4f8b\uff0c\u91cd\u70b9\u8bb2\u6e05\u5bfc\u5e08\u5173\u7cfb\u91cc\u90a3\u9053\u6700\u5bb9\u6613\u88ab\u8de8\u8d8a\u7684\u8fb9\u754c\u3002","permalink":"/docs/lifeforfun/storycraft/the-sage"},{"id":"lifeforfun/storycraft/readings","title":"\u6750\u6599\u4e0e\u4e66\u76ee\u62c6\u89e3","description":"\u4e0d\u53ea\u5217\u4e66\u5355\u3002\u628a\u4eba\u7269\u5851\u9020\u3001\u539f\u578b\u7ed3\u6784\u3001\u4eba\u683c\u5fc3\u7406\u5b66\u4e0e\u4e2d\u6587\u6750\u6599\u56db\u7c7b\u6765\u6e90\u9010\u4e2a\u62c6\u5f00\uff0c\u5199\u6e05\u6bcf\u672c\u89e3\u51b3\u4ec0\u4e48\u95ee\u9898\u3001\u80fd\u5e26\u8d70\u4ec0\u4e48\u3001\u6709\u54ea\u4e9b\u88ab\u53cd\u590d\u8bef\u8bfb\u7684\u5730\u65b9\u548c\u771f\u5b9e\u5b58\u5728\u7684\u4e89\u8bae\u3002","permalink":"/docs/lifeforfun/storycraft/readings"},{"id":"lifeforfun/storycraft/concepts","title":"\u6838\u5fc3\u6982\u5ff5\uff1a\u4eba\u7269\u51ed\u4ec0\u4e48\u201c\u7acb\u201d\u8d77\u6765","description":"\u7528\u4e00\u53f0\u201c\u6b32\u671b\u88ab\u963b\u788d\u3001\u88ab\u8feb\u9009\u62e9\u3001\u4ed8\u51fa\u4ee3\u4ef7\u201d\u7684\u673a\u5668\u6765\u5b9a\u4e49\u4eba\u7269\uff0c\u5e76\u5206\u6e05\u4e09\u7ec4\u6700\u5bb9\u6613\u88ab\u641e\u6df7\u7684\u6982\u5ff5\uff1a\u6241\u5e73\u4e0e\u5706\u5f62\u3001\u539f\u578b\u4e0e\u523b\u677f\u5370\u8c61\u3001\u6027\u683c\u4e0e\u52a8\u673a\u4e0e\u5f27\u7ebf\u3002","permalink":"/docs/lifeforfun/storycraft/concepts"},{"id":"lifeforfun/storycraft/the-caregiver","title":"\u7167\u987e\u8005\uff1a\u4ed8\u51fa\u3001\u63a7\u5236\u4e0e\u8017\u7aed","description":"\u7167\u987e\u8005\u662f\u6700\u8d34\u8fd1\u65e5\u5e38\u53c8\u6700\u5bb9\u6613\u88ab\u8bef\u8bfb\u7684\u539f\u578b\u3002\u8fd9\u7bc7\u5206\u6e05\u6ecb\u517b\u578b\u3001\u63a7\u5236\u578b\u3001\u6b89\u9053\u578b\u4e09\u79cd\u4e9a\u578b\uff0c\u7528\u300a\u98d8\u300b\u7684\u6885\u5170\u59ae\u3001\u300a\u4e1c\u4eac\u7269\u8bed\u300b\u7684\u7eaa\u5b50\u4e0e\u4e1c\u4e9a\u201c\u4e09\u660e\u6cbb\u4e00\u4ee3\u201d\u7167\u62a4\u5904\u5883\u505a\u6848\u4f8b\uff0c\u91cd\u70b9\u843d\u5728\u73b0\u5b9e\u91cc\u7684\u8fb9\u754c\u3001\u6c9f\u901a\u4e0e\u81ea\u6211\u53cd\u601d\u3002","permalink":"/docs/lifeforfun/storycraft/the-caregiver"},{"id":"lifeforfun/storycraft/life-transfer","title":"\u751f\u6d3b\u8fc1\u79fb\u603b\u7eb2\uff1a\u4ece\u6545\u4e8b\u4eba\u7269\u5230\u771f\u5b9e\u7684\u4eba","description":"\u628a\u8bfb\u4eba\u7269\u7684\u65b9\u6cd5\u7ffb\u8bd1\u6210\u73b0\u5b9e\u80fd\u529b\uff1a\u8bc6\u4eba\u56db\u6b65\u6cd5\u3001\u628a\u4eba\u7684\u95ee\u9898\u7ffb\u8bd1\u6210\u4e8b\u7684\u8bdd\u3001\u5171\u60c5\u7684\u4e09\u5c42\u4e0e\u8fb9\u754c\u3001\u8bbe\u8fb9\u754c\u7684\u56db\u6b65\u3001\u51b2\u7a81\u590d\u76d8\u8868\u3001\u52a8\u673a\u7684\u4e09\u5c42\u8be2\u95ee\u3001\u81ea\u6211\u53cd\u601d\u4e0e\u91cd\u5199\u81ea\u5df1\u7684\u6545\u4e8b\u3002\u6bcf\u4e00\u8282\u90fd\u914d\u53ef\u6267\u884c\u7684\u8868\u683c\u6216\u7ec3\u4e60\u3002","permalink":"/docs/lifeforfun/storycraft/life-transfer"},{"id":"lifeforfun/storycraft/the-hero","title":"\u82f1\u96c4\uff1a\u628a\u4ee3\u4ef7\u625b\u6210\u610f\u4e49","description":"\u62c6\u89e3\u82f1\u96c4\u539f\u578b\u7684\u5224\u636e\u3001\u4e09\u79cd\u4e9a\u578b\u4e0e\u5851\u9020\u624b\u6cd5\uff0c\u7528\u300a\u8001\u4eba\u4e0e\u6d77\u300b\u300a\u8096\u7533\u514b\u7684\u6551\u8d4e\u300b\u4e0e\u7ef4\u514b\u591a\xb7\u5f17\u5170\u514b\u5c14\u7684\u516c\u5f00\u81ea\u8ff0\u505a\u6848\u4f8b\uff0c\u518d\u63a8\u6f14\u82f1\u96c4\u578b\u7684\u4eba\u5728\u73b0\u5b9e\u5173\u7cfb\u91cc\u7684\u6c9f\u901a\u3001\u5171\u60c5\u4e0e\u8fb9\u754c\u3002","permalink":"/docs/lifeforfun/storycraft/the-hero"},{"id":"lifeforfun/storycraft/the-shadow","title":"\u9634\u5f71\u4e0e\u5bf9\u624b\uff1a\u51b2\u7a81\u7684\u53e6\u4e00\u9762\u4e5f\u662f\u4eba","description":"\u9634\u5f71\u6709\u4e24\u5c42\u542b\u4e49\u2014\u2014\u8363\u683c\u610f\u4e49\u4e0a\u88ab\u81ea\u5df1\u5426\u8ba4\u7684\u90a3\u90e8\u5206\u81ea\u6211\uff0c\u4ee5\u53ca\u53d9\u4e8b\u91cc\u4e0e\u4e3b\u89d2\u4e89\u593a\u540c\u4e00\u4ef6\u4e1c\u897f\u7684\u5bf9\u7acb\u65b9\u3002\u8fd9\u7bc7\u7528\u300a\u60b2\u60e8\u4e16\u754c\u300b\u7684\u6c99\u5a01\u3001\u300a\u7edd\u547d\u6bd2\u5e08\u300b\u7684\u6c83\u5c14\u7279\xb7\u6000\u7279\u4e0e\u6e05\u4ee3\u548c\u73c5\u505a\u6848\u4f8b\uff0c\u91cd\u70b9\u843d\u5728\u9634\u5f71\u6295\u5c04\u3001\u51b2\u7a81\u590d\u76d8\u4e0e\u201c\u5171\u60c5\u4e0d\u7b49\u4e8e\u8d66\u514d\u201d\u7684\u8fb9\u754c\u3002","permalink":"/docs/lifeforfun/storycraft/the-shadow"},{"id":"lifeforfun/storycraft/the-trickster","title":"\u9a97\u5b50\u4e0e\u6405\u5c40\u8005\uff1a\u771f\u8bda\u4e0e\u64cd\u7eb5\u4e4b\u95f4","description":"\u6405\u5c40\u8005\u4e0d\u5efa\u7acb\u79e9\u5e8f\u4e5f\u4e0d\u6467\u6bc1\u79e9\u5e8f\uff0c\u4ed6\u66b4\u9732\u79e9\u5e8f\u3002\u8fd9\u7bc7\u7528\u300a\u897f\u6e38\u8bb0\u300b\u7684\u5b59\u609f\u7a7a\u3001\u300a\u98de\u8d8a\u75af\u4eba\u9662\u300b\u7684\u9ea6\u514b\u58a8\u83f2\u4e0e\u5f17\u5170\u514b\xb7\u963f\u5df4\u5185\u5c14\u7684\u516c\u5f00\u81ea\u8ff0\u505a\u6848\u4f8b\uff0c\u8bb2\u6e05\u6405\u5c40\u8005\u4e0e\u9a97\u5b50\u7684\u5206\u754c\u7ebf\uff0c\u4ee5\u53ca\u5982\u4f55\u5728\u8bc6\u4eba\u65f6\u4e0d\u88ab\u9b45\u529b\u5e26\u8d70\u3002","permalink":"/docs/lifeforfun/storycraft/the-trickster"}],"unlisted":false}}')}}]);